package com.soumyajit.gradlemc.investigation.storage;
import com.soumyajit.gradlemc.investigation.*;import java.time.*;import java.util.*;
public record InvestigationRetentionPlan(List<Candidate> candidates){public record Candidate(InvestigationId id,long estimatedBytes,List<String> reasons){public Candidate{reasons=List.copyOf(reasons);}}public InvestigationRetentionPlan{candidates=List.copyOf(candidates);}public static InvestigationRetentionPlan plan(List<InvestigationIndexEntry> entries,Map<InvestigationId,Long> bytes,InvestigationRetentionPolicy policy,Instant now){List<InvestigationIndexEntry> terminal=entries.stream().filter(e->e.state().terminal()).sorted(Comparator.comparing(InvestigationIndexEntry::createdAt)).toList();Set<InvestigationId>keep=new HashSet<>(terminal.stream().skip(Math.max(0,terminal.size()-policy.minimumRecent())).map(InvestigationIndexEntry::id).toList());long total=terminal.stream().mapToLong(e->Math.max(0,bytes.getOrDefault(e.id(),0L))).sum();List<Candidate>out=new ArrayList<>();int count=terminal.size();for(var e:terminal){if(keep.contains(e.id()))continue;List<String>reasons=new ArrayList<>();long size=Math.max(0,bytes.getOrDefault(e.id(),0L));if(count>policy.maximumSessions())reasons.add("maximum-session-count");if(total>policy.maximumBytes())reasons.add("maximum-bytes");if(e.endedAt()!=null&&e.endedAt().isBefore(now.minus(policy.maximumAge())))reasons.add("maximum-age");if(!reasons.isEmpty()){out.add(new Candidate(e.id(),size,reasons));count--;total-=size;}}return new InvestigationRetentionPlan(out);}}
